import{_ as t,o as e,c as a,Q as d}from"./chunks/framework.48927342.js";const p=JSON.parse('{"title":"Talking About Upcoming Plans","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/practice/dialogues/05-weekend-plans.md","filePath":"en/more/maltese/practice/dialogues/05-weekend-plans.md"}'),r={name:"en/more/maltese/practice/dialogues/05-weekend-plans.md"},o=d('<h1 id="talking-about-upcoming-plans" tabindex="-1">Talking About Upcoming Plans <a class="header-anchor" href="#talking-about-upcoming-plans" aria-label="Permalink to &quot;Talking About Upcoming Plans&quot;">​</a></h1><p><strong>Scenario:</strong> Anna and Mark talk about plans for today, tomorrow, this weekend, next week, next month, and next year.</p><h2 id="complete-dialogue" tabindex="-1">Complete Dialogue <a class="header-anchor" href="#complete-dialogue" aria-label="Permalink to &quot;Complete Dialogue&quot;">​</a></h2><p><strong>Anna:</strong> X&#39;għandek tagħmel illum u għada?</p><p><strong>Mark:</strong> Illum naħdem mid-dar u filgħaxija nistudja l-Malti. Għada se mmur l-isptar ma&#39; ommi.</p><p><strong>Anna:</strong> X&#39;se tagħmel fi tmiem il-ġimgħa?</p><p><strong>Mark:</strong> Se niltaqa&#39; mal-ħbieb għal kafè.</p><p><strong>Anna:</strong> Għandek pjanijiet għall-ġimgħa d-dieħla?</p><p><strong>Mark:</strong> Iva. Nhar it-Tlieta se nżur lill-familja tiegħi.</p><p><strong>Anna:</strong> U x-xahar id-dieħel?</p><p><strong>Mark:</strong> Se nivvjaġġa lejn Għawdex għal ftit jiem.</p><p><strong>Anna:</strong> X&#39;tixtieq tagħmel is-sena d-dieħla?</p><p><strong>Mark:</strong> Nixtieq nitgħallem aktar il-Malti u nsiefer.</p><h2 id="sentence-by-sentence-translation-and-word-notes" tabindex="-1">Sentence-by-Sentence Translation and Word Notes <a class="header-anchor" href="#sentence-by-sentence-translation-and-word-notes" aria-label="Permalink to &quot;Sentence-by-Sentence Translation and Word Notes&quot;">​</a></h2><h3 id="_1-anna" tabindex="-1">1. Anna <a class="header-anchor" href="#_1-anna" aria-label="Permalink to &quot;1. Anna&quot;">​</a></h3><p><strong>Malti:</strong> X&#39;għandek tagħmel illum u għada?</p><p><strong>Translation:</strong> What are you doing today and tomorrow?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>X&#39;</td><td>what</td><td>Short form of <code>xiex</code>, often attached to the following word</td></tr><tr><td>għandek</td><td>you have; you need to</td><td>Second-person singular form of <code>għand</code></td></tr><tr><td>tagħmel</td><td>you do; you make</td><td>Second-person singular form</td></tr><tr><td>illum</td><td>today</td><td>Time adverb</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>għada</td><td>tomorrow</td><td>Time adverb</td></tr></tbody></table><h3 id="_2-mark" tabindex="-1">2. Mark <a class="header-anchor" href="#_2-mark" aria-label="Permalink to &quot;2. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Illum naħdem mid-dar u filgħaxija nistudja l-Malti.</p><p><strong>Translation:</strong> Today I work from home, and in the evening I study Maltese.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Illum</td><td>today</td><td>Time adverb</td></tr><tr><td>naħdem</td><td>I work</td><td>First-person singular form</td></tr><tr><td>mid-dar</td><td>from home; at home</td><td>Contracted form of <code>minn</code> “from” + <code>id-dar</code> “the house”</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>filgħaxija</td><td>in the evening</td><td>Time expression</td></tr><tr><td>nistudja</td><td>I study</td><td>First-person singular form</td></tr><tr><td>l-Malti</td><td>the Maltese language</td><td>Language name with the definite article</td></tr></tbody></table><h3 id="_3-mark" tabindex="-1">3. Mark <a class="header-anchor" href="#_3-mark" aria-label="Permalink to &quot;3. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Għada se mmur l-isptar ma&#39; ommi.</p><p><strong>Translation:</strong> Tomorrow I&#39;ll go to the hospital with my mother.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għada</td><td>tomorrow</td><td>Time adverb</td></tr><tr><td>se</td><td>will; going to</td><td>Common future marker</td></tr><tr><td>mmur</td><td>I go</td><td>First-person singular form</td></tr><tr><td>l-isptar</td><td>the hospital</td><td>Definite article + <code>isptar</code></td></tr><tr><td>ma&#39;</td><td>with</td><td>Preposition</td></tr><tr><td>ommi</td><td>my mother</td><td><code>omm</code> “mother” + first-person possessive suffix <code>-i</code></td></tr></tbody></table><h3 id="_4-anna" tabindex="-1">4. Anna <a class="header-anchor" href="#_4-anna" aria-label="Permalink to &quot;4. Anna&quot;">​</a></h3><p><strong>Malti:</strong> X&#39;se tagħmel fi tmiem il-ġimgħa?</p><p><strong>Translation:</strong> What are you going to do this weekend?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>X&#39;</td><td>what</td><td>Short question form</td></tr><tr><td>se</td><td>will; going to</td><td>Future marker</td></tr><tr><td>tagħmel</td><td>you do; you make</td><td>Second-person singular form</td></tr><tr><td>fi</td><td>in; at</td><td>Preposition</td></tr><tr><td>tmiem</td><td>end</td><td>Combines with the following words in a time expression</td></tr><tr><td>il-ġimgħa</td><td>the week</td><td><code>tmiem il-ġimgħa</code> as a whole means “weekend”</td></tr></tbody></table><h3 id="_5-mark" tabindex="-1">5. Mark <a class="header-anchor" href="#_5-mark" aria-label="Permalink to &quot;5. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Se niltaqa&#39; mal-ħbieb għal kafè.</p><p><strong>Translation:</strong> I&#39;ll meet my friends for coffee.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Se</td><td>will; going to</td><td>Future marker</td></tr><tr><td>niltaqa&#39;</td><td>I meet</td><td>First-person singular form; the apostrophe is part of the spelling</td></tr><tr><td>mal-ħbieb</td><td>with the friends</td><td>Contracted <code>ma&#39;</code> “with” + <code>il-ħbieb</code> “the friends”</td></tr><tr><td>għal</td><td>for</td><td>Expresses purpose here</td></tr><tr><td>kafè</td><td>coffee</td><td>Masculine noun; refers here to having coffee</td></tr></tbody></table><h3 id="_6-anna" tabindex="-1">6. Anna <a class="header-anchor" href="#_6-anna" aria-label="Permalink to &quot;6. Anna&quot;">​</a></h3><p><strong>Malti:</strong> Għandek pjanijiet għall-ġimgħa d-dieħla?</p><p><strong>Translation:</strong> Do you have plans for next week?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għandek</td><td>you have</td><td>Second-person singular form of <code>għand</code></td></tr><tr><td>pjanijiet</td><td>plans</td><td>Plural of <code>pjan</code></td></tr><tr><td>għall-ġimgħa</td><td>for the week</td><td>Contracted <code>għal</code> + <code>il-ġimgħa</code></td></tr><tr><td>d-dieħla</td><td>coming; next</td><td>Feminine form agreeing with <code>ġimgħa</code></td></tr></tbody></table><h3 id="_7-mark" tabindex="-1">7. Mark <a class="header-anchor" href="#_7-mark" aria-label="Permalink to &quot;7. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Iva. Nhar it-Tlieta se nżur lill-familja tiegħi.</p><p><strong>Translation:</strong> Yes. On Tuesday I&#39;ll visit my family.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Iva</td><td>yes</td><td>Affirmative response</td></tr><tr><td>Nhar</td><td>on the day of</td><td>Introduces a weekday or date</td></tr><tr><td>it-Tlieta</td><td>Tuesday</td><td>Weekday commonly used with the definite article</td></tr><tr><td>se</td><td>will; going to</td><td>Future marker</td></tr><tr><td>nżur</td><td>I visit</td><td>First-person singular form</td></tr><tr><td>lill-familja</td><td>the family (as object)</td><td>Personal object marker <code>lil</code> written with the definite article</td></tr><tr><td>tiegħi</td><td>my; mine</td><td>Possessive pronoun</td></tr></tbody></table><h3 id="_8-anna" tabindex="-1">8. Anna <a class="header-anchor" href="#_8-anna" aria-label="Permalink to &quot;8. Anna&quot;">​</a></h3><p><strong>Malti:</strong> U x-xahar id-dieħel?</p><p><strong>Translation:</strong> And what about next month?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>U</td><td>and; so</td><td>Connects to the previous topic or introduces a follow-up</td></tr><tr><td>x-xahar</td><td>the month; this month</td><td>Definite form of <code>xahar</code> “month”</td></tr><tr><td>id-dieħel</td><td>coming; next</td><td>Masculine form agreeing with <code>xahar</code></td></tr></tbody></table><h3 id="_9-mark" tabindex="-1">9. Mark <a class="header-anchor" href="#_9-mark" aria-label="Permalink to &quot;9. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Se nivvjaġġa lejn Għawdex għal ftit jiem.</p><p><strong>Translation:</strong> I&#39;ll travel to Gozo for a few days next month.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Se</td><td>will; going to</td><td>Future marker; “next month” is understood from the question</td></tr><tr><td>nivvjaġġa</td><td>I travel</td><td>First-person singular form</td></tr><tr><td>lejn</td><td>toward; to</td><td>Directional preposition</td></tr><tr><td>Għawdex</td><td>Gozo</td><td>Island in the Maltese archipelago</td></tr><tr><td>għal</td><td>for; lasting</td><td>Introduces a duration here</td></tr><tr><td>ftit</td><td>a few; a little</td><td>Quantifier</td></tr><tr><td>jiem</td><td>days</td><td>Plural of <code>jum</code> “day”</td></tr></tbody></table><h3 id="_10-anna" tabindex="-1">10. Anna <a class="header-anchor" href="#_10-anna" aria-label="Permalink to &quot;10. Anna&quot;">​</a></h3><p><strong>Malti:</strong> X&#39;tixtieq tagħmel is-sena d-dieħla?</p><p><strong>Translation:</strong> What would you like to do next year?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>X&#39;</td><td>what</td><td>Short question form</td></tr><tr><td>tixtieq</td><td>you would like; you want</td><td>Second-person singular form, often used for polite questions</td></tr><tr><td>tagħmel</td><td>you do; you make</td><td>Second-person singular form</td></tr><tr><td>is-sena</td><td>the year</td><td>Definite form of <code>sena</code> “year”</td></tr><tr><td>d-dieħla</td><td>coming; next</td><td>Feminine form agreeing with <code>sena</code></td></tr></tbody></table><h3 id="_11-mark" tabindex="-1">11. Mark <a class="header-anchor" href="#_11-mark" aria-label="Permalink to &quot;11. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Nixtieq nitgħallem aktar il-Malti u nsiefer.</p><p><strong>Translation:</strong> I&#39;d like to learn more Maltese and travel abroad.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nixtieq</td><td>I would like; I want</td><td>First-person singular form</td></tr><tr><td>nitgħallem</td><td>I learn</td><td>First-person singular form; contains medial <code>għ</code></td></tr><tr><td>aktar</td><td>more; further</td><td>Adverb of degree</td></tr><tr><td>il-Malti</td><td>the Maltese language</td><td>Language name</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>nsiefer</td><td>I travel abroad</td><td>First-person singular form</td></tr></tbody></table><h2 id="quick-reference-time-expressions" tabindex="-1">Quick Reference: Time Expressions <a class="header-anchor" href="#quick-reference-time-expressions" aria-label="Permalink to &quot;Quick Reference: Time Expressions&quot;">​</a></h2><ul><li><code>illum</code>: today</li><li><code>għada</code>: tomorrow</li><li><code>fi tmiem il-ġimgħa</code>: this weekend</li><li><code>il-ġimgħa d-dieħla</code>: next week</li><li><code>ix-xahar id-dieħel</code>: next month</li><li><code>is-sena d-dieħla</code>: next year</li></ul>',60),n=[o];function i(l,s,h,m,g,c){return e(),a("div",null,n)}const f=t(r,[["render",i]]);export{p as __pageData,f as default};
